-- Validation cohort 1: read-only live check, run immediately before submission. Writes nothing.
-- Status: Living (2026-10-29). Expected for an admissible cohort: cands 100, held_by_url 0, held_by_key 0,
-- held_by_path 0, stems_with_rows 100, rows_corroborated = rows_, stems_mismatch 0, key_ok = rows_.
-- Signatures: md5(pq_norm(house)|pq_norm(subject)|pq_norm(ministry)|pq_date(answered_on)) from each record's citation
-- (pq-validation-cohort.py); the rows side uses the server's own pq_norm / pq_date, as F266 admission does.
-- Rule 6 (2026-10-29): production reads only inside a read-only transaction that is rolled back.
begin transaction read only;
with c as (select split_part(split_part(x, ':', 1), '/', 1) session, split_part(split_part(x, ':', 1), '/', 2) stem, split_part(x, ':', 2) sig
             from unnest(string_to_array('182/AU2668_StrtYL:e60b959abc39ee718b890e34a94b2b8a,182/AU2681_PM6n4K:aba44b713a9dc608a29966708895d62c,182/AU2685_2IXB66:1aeacb3dd17c95e5dad4492bcd7160b2,182/AU2703_2PmFCl:aba955ef09453145668507a3d1a776a4,182/AU2713_iFJKOI:e3d07cb141cbe2dab6f1ef6870bf5990,182/AU2719_gP5McI:2bfc1cb907ef41f10de822536e211f7c,182/AU2724_j2bR7T:b699fdd13cae4cd605c7c42a5fc2d6e3,182/AU2725_cw2PJl:7c387b9a496c0d51f72725c45ca784fd,182/AU2727_2Veupg:38fd7dec27a212a5a735d96a2b0bbdd4,182/AU2730_EGJcui:ca78bd71b5f38994c6a46dd403f4fe8d,182/AU2731_yj8KJ1:48c9a28989de8c2957cbbb5aa59e83dd,182/AU2732_rhiBpf:224b0ac22c69047ef078748ddd9345ba,182/AU2735_Eoqwzl:e08dbd98cc8ba1a9fe9a39815aa593a3,182/AU2736_La2tYH:e864610ce8f1ebcceb03e27f1dd865ad,182/AU2739_sDP7PH:4827198c8c60f12bd120eb9e3dc81db6,182/AU2745_xosy5x:d1714362fc4f90ae83c7dc90fab84b0f,182/AU2749_iYV6mB:9c68efeee2f9abffadcd0c9227893252,182/AU2750_AL4LyG:440b9dd6aeceed147bbdb432a80ccd4d,182/AU2752_sadzKB:17b016e3cb05187959321bc9d8c9e4f2,182/AU2757_861A0s:5f0b2ce4ac26f0069cb62ba74b7df5e3,182/AU2758_6qbhHR:8717f31831d21e3c63271f319532a60d,182/AS210_uxQZSI:15b6b3fb852f728bdfb5443fe2867481,182/AS212_OIJxEt:7a93a92d88d8f88ac020f8057bc43311,182/AS217_8QyWKt:9d2c13cd8cd82b92373a8445c9d1066b,182/AS220_iNFz3I:f1d304fd8c5d243b3037df302178d3a6,182/AU2303_lPadDs:1069540fbceefb94684a1d8eae742d38,182/AU2305_1qp5Ga:f6c1d9d32e679ff13c1bf1a03f38a7ef,182/AU2307_tOxiK0:c57a06897fd81346fb33c3ca910f88d2,182/AU2315_adKH4B:645a3541712bfa275dbc30705f4c3a39,182/AU2319_ZHPDCb:82ae20b8e19b21029baca431918178d1,182/AU2320_DTmyzX:603e40500dc9727007438728dde0914d,182/AU2326_TuiApZ:036fc9ead2f92918eb1eb41ffb366223,182/AU2337_0foks0:f3bd381accfc1bbc2441e89f009f648f,182/AU2338_Nv4y7K:a6dc39c39b342cadd208dc3a0353cbe6,182/AU2339_1E8QMD:d4e454122ee92c7e313468bf2db80b9a,182/AU2340_Y6WP08:31888f043b4c50b01fd8fce26560bc5e,182/AU2342_O9IEHK:8dd92251ee3b00b5a3506b74cfbfcdf7,182/AU2344_g6C2Lc:c39b867b85db37005a38cce7c9d3bfff,182/AU2354_a6dggI:b643fc